import java.io.IOException;
import java.io.InputStream;

import org.apache.commons.compress.utils.IOUtils;

public abstract class ArchiveInputStream extends InputStream {

    /**
     * Returns the next Archive Entry in this Stream.
     * @return the next entry
     * @throws IOException if the next entry could not be read
     */
    public abstract ArchiveEntry getNextEntry() throws IOException;

    /**
     * Converts the outcome of a one-byte bulk read into the value that
     * read() returns. A count of -1 means that the bulk read reached the
     * end of the stream; any other count means that the byte was read.
     * The octet is passed on unchanged.
     *
     * @param count the number the bulk read returned
     * @param octet the byte the bulk read stored, as an int
     * @return the value IOUtils.readValue gives for (count == -1) and octet
     */
    public static int toReadValue(int count, int octet) {
        return IOUtils.readValue(count == -1, octet);
    }

