/**
 * Gives the value that InputStream.read() returns for one byte:
 * -1 at the end of the stream, otherwise the byte itself.
 * <p>
 * The octet must already be an unsigned byte value from 0 to 255, so
 * that it cannot be taken for the end marker -1; it is returned as given.
 *
 * @param atEnd
 *            whether the end of the stream was reached
 * @param octet
 *            the byte, as a value from 0 to 255
 * @return -1 if atEnd is true, otherwise octet
 */
public static int readValue(final boolean atEnd, final int octet) {
    return atEnd ? -1 : octet;
}

